/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; requeue puts a message back at the tail for a later retry.
 *
 * Every entry is stamped with a monotonically increasing, non-enumerable `seq`
 * recording its enqueue order. A requeued message keeps the seq it arrived
 * with, so a retry never loses its original position in the per-key sequence.
 * `hasEarlierPending(key, seq)` reports whether an earlier message with the
 * same key is still unfinished; the pump uses it to hold later same-key
 * messages back, which is what preserves per-key ordering across retries.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  let nextSeq = 0
  function stampSeq(message) {
    if (message.seq === undefined) {
      Object.defineProperty(message, 'seq', {
        value: ++nextSeq,
        enumerable: false,
        writable: true,
        configurable: true,
      })
    }
    return message
  }
  return {
    enqueue(message) {
      entries.push(stampSeq({ ...message, attempts: message.attempts ?? 0 }))
    },
    dequeue() {
      for (let i = 0; i < entries.length; i++) {
        if (!done.has(entries[i].id)) return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      entries.push(stampSeq(message))
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
    hasEarlierPending(key, seq) {
      for (const entry of entries) {
        if (!done.has(entry.id) && entry.key === key && entry.seq < seq) return true
      }
      return false
    },
  }
}

/**
 * Delivery pump: dequeue → skip duplicates → deliver → ack + record + emit, or
 * requeue with backoff on failure.
 *
 * Effectively-once: the sink is written only at the success boundary — after
 * processMessage succeeds, the pump acks the queue entry, records the id in the
 * dedup window, and emits to the sink, together and once per id. A failed
 * attempt (including one where the downstream already accepted the message but
 * reported failure) touches neither the sink nor the dedup window, so the
 * retry either succeeds — producing exactly one delivery — or is eventually
 * abandoned via sink.failed without any delivery.
 *
 * Per-key ordering: a message that is waiting on its backoff deadline, or that
 * has an earlier unfinished message with the same key, is requeued at the tail
 * and deferred. The earlier message must resolve first, so a retry never lets
 * a later same-key message overtake it.
 *
 * Liveness: when one full pass over the pending messages defers all of them
 * and the injected clock has not advanced during that pass, nothing can make
 * progress until time moves, so run() returns instead of spinning forever on a
 * frozen clock.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)
  return {
    run(steps = Infinity) {
      let idle = 0
      let idleStartNow = null
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break
        const now = clock.now()
        const waitingOnBackoff = message.retryAt !== undefined && now < message.retryAt
        const waitingOnKey =
          message.key !== undefined &&
          message.seq !== undefined &&
          typeof queue.hasEarlierPending === 'function' &&
          queue.hasEarlierPending(message.key, message.seq)
        if (waitingOnBackoff || waitingOnKey) {
          queue.requeue(message)
          if (idle === 0) idleStartNow = now
          idle++
          if (idle > queue.pending().length && now <= idleStartNow) break
          continue
        }
        if (dedup.isDuplicate(message.id, now)) {
          queue.ack(message.id)
          idle = 0
          idleStartNow = null
          continue
        }
        let ok = true
        try {
          ok = Boolean(processMessage(message))
        } catch {
          ok = false
        }
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            idle = 0
            idleStartNow = null
            continue
          }
          message.retryAt = retrier.scheduleRetry(message.attempts, now)
          queue.requeue(message)
          continue
        }
        queue.ack(message.id)
        dedup.record(message.id, now)
        sink.emit(message)
        idle = 0
        idleStartNow = null
      }
    },
  }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from '../src/index.js'

// Clock that advances a fixed amount on every read, so a backoff deadline set
// during one iteration is reached within the same run().
function steppingClock(step = 100) {
  let now = 0
  return { now: () => (now += step) }
}

test('pump: an attempt that fails after the downstream accepted delivers exactly once', () => {
  const queue = createQueue()
  const sink = createSink()
  let calls = 0
  const downstream = new Set()
  const processMessage = (message) => {
    calls++
    downstream.add(message.id) // downstream accepts, then the attempt "fails"
    return calls > 1
  }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock: steppingClock(),
    processMessage,
  })
  pump.run(50)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(calls, 2)
})

test('pump: a later message with the same key never overtakes a retrying earlier one', () => {
  const queue = createQueue()
  const sink = createSink()
  let first = true
  const processMessage = (message) => {
    if (message.id === 'm1' && first) {
      first = false
      return false // m1 fails once, downstream never saw it
    }
    return true
  }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock: steppingClock(),
    processMessage,
  })
  pump.run(50)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

test('pump: run() terminates on a frozen clock while a message is backing off', () => {
  const queue = createQueue()
  const sink = createSink()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 1000 }),
    sink,
    clock: { now: () => 0 },
    processMessage: () => false,
  })
  pump.run() // must not hang
  assert.deepEqual(sink.deliveredIds(), [])
  assert.equal(queue.pending().length, 1)
})

test('pump: exhausted message is reported failed once and never emitted', () => {
  const queue = createQueue()
  const sink = createSink()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock: steppingClock(),
    processMessage: () => false,
  })
  pump.run(50)
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(sink.deliveredIds(), [])
})

test('pump: a duplicate id queued behind a retrying original is delivered once', () => {
  const queue = createQueue()
  const sink = createSink()
  let calls = 0
  const processMessage = () => ++calls >= 3 // fails twice, then succeeds
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue,
    dedup: createDedup({ windowMs: 100000 }),
    sink,
    clock: steppingClock(),
    processMessage,
  })
  pump.run(100)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

// Scratch adversarial fuzz for relaypump guarantees. Not part of the test suite.
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

// Deterministic PRNG (mulberry32) so failures are reproducible.
function rng(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const KEYS = ['K1', 'K2', 'K3']
let checked = 0

function scenario(seed) {
  const rand = rng(seed)
  const pick = (arr) => arr[Math.floor(rand() * arr.length)]
  const chance = (p) => rand() < p

  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 1e9 })
  const maxAttempts = 1 + Math.floor(rand() * 4)

  // Clock styles: frozen / fixed step / random walk with occasional dips.
  const style = pick(['frozen', 'step', 'walk'])
  let t = 0
  const stepSize = pick([1, 17, 100, 250])
  const clock = {
    now: () => {
      if (style === 'frozen') return 0
      if (style === 'step') { t += stepSize; return t }
      t += Math.floor(rand() * 500) - (chance(0.1) ? 60 : 0)
      if (t < 0) t = 0
      return t
    },
  }

  // Per-id delivery script: how many leading failures (or a first-call throw).
  const failPlan = new Map() // id -> remaining failures
  const throwOnce = new Set()
  const firstEnqueue = { K1: [], K2: [], K3: [] } // per-key first-enqueue order
  const enqueuedIds = new Set()
  const pendingOrDelivered = new Set()
  let idCounter = 0

  const pump = createPump({
    queue, dedup, sink, clock, maxAttempts,
    processMessage(message) {
      if (chance(0.05)) {
        // Mid-delivery enqueue of a fresh message.
        const key = pick(KEYS)
        const id = `x${idCounter++}`
        firstEnqueue[key].push(id)
        enqueuedIds.add(id)
        pendingOrDelivered.add(id)
        failPlan.set(id, chance(0.5) ? 0 : Math.floor(rand() * 3))
        queue.enqueue({ id, key, payload: 0 })
      }
      if (throwOnce.has(message.id)) {
        throwOnce.delete(message.id)
        throw new Error('transient downstream crash')
      }
      const left = failPlan.get(message.id) ?? 0
      if (left > 0) {
        failPlan.set(message.id, left - 1)
        return false
      }
      return true
    },
  })

  const events = 8 + Math.floor(rand() * 8)
  for (let e = 0; e < events; e++) {
    if (chance(0.2) && pendingOrDelivered.size > 0) {
      // Duplicate id, only while the id is still pending or already delivered
      // (a re-send after abandonment is a brand-new message, out of scope).
      const id = pick([...pendingOrDelivered])
      const key = [...firstEnqueue.K1, ...firstEnqueue.K2, ...firstEnqueue.K3].includes(id)
        ? (firstEnqueue.K1.includes(id) ? 'K1' : firstEnqueue.K2.includes(id) ? 'K2' : 'K3')
        : 'K1'
      queue.enqueue({ id, key, payload: 0 })
    } else {
      const key = pick(KEYS)
      const id = `m${idCounter++}`
      firstEnqueue[key].push(id)
      enqueuedIds.add(id)
      pendingOrDelivered.add(id)
      const plan = chance(0.15) ? 99 : Math.floor(rand() * 3) // 99 => always fails
      failPlan.set(id, plan)
      if (chance(0.1)) throwOnce.add(id)
      queue.enqueue({ id, key, payload: 0 })
    }
    if (chance(0.5)) pump.run(1 + Math.floor(rand() * 40))
  }

  // Drain: bounded number of extra runs.
  for (let i = 0; i < 400 && queue.pending().length > 0; i++) {
    pump.run(1 + Math.floor(rand() * 60))
  }

  // --- Invariants ---
  const delivered = sink.deliveredIds()
  const failed = new Set(sink.failedIds())

  // 1. Effectively-once: no id delivered twice.
  const seen = new Set()
  for (const id of delivered) {
    if (seen.has(id)) throw new Error(`seed ${seed}: duplicate delivery of ${id}`)
    seen.add(id)
    if (!enqueuedIds.has(id)) throw new Error(`seed ${seed}: delivered unknown id ${id}`)
    if (failed.has(id)) throw new Error(`seed ${seed}: id ${id} both delivered and failed`)
  }

  // 2. Per-key order: delivered ids of a key follow first-enqueue order with
  //    abandoned (failed, never delivered) ids removed.
  for (const key of KEYS) {
    const expected = firstEnqueue[key].filter((id) => !failed.has(id))
    const actual = delivered.filter((id) => firstEnqueue[key].includes(id))
    let j = 0
    for (const id of actual) {
      while (j < expected.length && expected[j] !== id) j++
      if (j >= expected.length) {
        throw new Error(`seed ${seed}: key ${key} out of order: [${actual}] vs [${expected}]`)
      }
      j++
    }
    // 3. Everything not failed should eventually drain (liveness with a live clock).
    if (style !== 'frozen') {
      const stuck = expected.filter((id) => !seen.has(id))
      if (stuck.length > 0 && queue.pending().length > 0) {
        // Only acceptable if those ids are still legitimately pending.
        const pendingIds = new Set(queue.pending().map((m) => m.id))
        for (const id of stuck) {
          if (!pendingIds.has(id)) throw new Error(`seed ${seed}: key ${key} lost message ${id}`)
        }
      }
    }
  }
  checked++
}

for (let seed = 1; seed <= 3000; seed++) scenario(seed)
console.log(`fuzz ok: ${checked} scenarios, invariants held`)
